/**
 * Golden-vector check for the ESF-551 scale protocol and its body-composition
 * algorithm.
 *
 * `esf551-golden.json` was generated by running the reverse-engineered Python
 * reference implementation (etekcity_esf551_ble) over 400 synthetic BLE frames
 * and 900 body-composition inputs. This asserts Salutt reproduces every value
 * exactly — not approximately. Body fat is *floored* off a BMI derived from the
 * weight, so a one-in-the-last-decimal rounding difference propagates into
 * every downstream metric.
 *
 * Run with: npm run test:scale
 */
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import { parseFrame } from '../src/lib/scale'
import { bodyComposition } from '../src/lib/bodyComp'

interface Golden {
  source: string
  frames: { hex: string; expected: { weight: number; impedance?: number; display_unit: number } | null }[]
  comp: { in: [number, number, number, number, number, boolean] } & Record<string, number>[]
}

const here = dirname(fileURLToPath(import.meta.url))
const golden = JSON.parse(readFileSync(join(here, 'esf551-golden.json'), 'utf8')) as Golden

const failures: string[] = []
const fail = (msg: string) => {
  if (failures.length < 20) failures.push(msg)
  else if (failures.length === 20) failures.push('…')
}

/* ------------------------------------------------------------- frames */

let frameChecks = 0
for (const f of golden.frames) {
  const bytes = Uint8Array.from(f.hex.match(/../g)!.map((h) => parseInt(h, 16)))
  const got = parseFrame(new DataView(bytes.buffer))
  const exp = f.expected
  if (!exp) continue

  frameChecks++
  const unit = (['kg', 'lb', 'st'] as const)[exp.display_unit]
  if (!got) {
    fail(`frame ${f.hex}: parsed as null`)
    continue
  }
  if (got.kg !== exp.weight) fail(`frame ${f.hex}: weight ${got.kg} != ${exp.weight}`)
  if ((got.impedance ?? null) !== (exp.impedance ?? null)) {
    fail(`frame ${f.hex}: impedance ${got.impedance} != ${exp.impedance}`)
  }
  if (got.displayUnit !== unit) fail(`frame ${f.hex}: unit ${got.displayUnit} != ${unit}`)
}

/* -------------------------------------------------------- composition */

const KEYS = [
  'bmi',
  'bodyFatPct',
  'fatFreeKg',
  'subcutaneousFatPct',
  'visceralFat',
  'waterPct',
  'bmrKcal',
  'skeletalMusclePct',
  'muscleKg',
  'boneKg',
  'proteinPct',
] as const

let compChecks = 0
for (const c of golden.comp as unknown as (Record<string, number> & {
  in: [number, number, number, number, number, boolean]
})[]) {
  const [weight, heightM, age, sex, impedance, athlete] = c.in
  const got = bodyComposition(weight, heightM * 100, age, sex === 0 ? 'male' : 'female', impedance, athlete)
  if (!got) {
    fail(`comp ${JSON.stringify(c.in)}: null`)
    continue
  }
  for (const k of KEYS) {
    compChecks++
    const g = (got as unknown as Record<string, number>)[k]
    if (g !== c[k]) fail(`comp ${JSON.stringify(c.in)} ${k}: ${g} != ${c[k]}`)
  }
}

/* -------------------------------------------------------------- report */

console.log(`reference: ${golden.source}`)
console.log(`frames:      ${frameChecks} checked`)
console.log(`composition: ${compChecks} values checked`)

if (failures.length) {
  console.error(`\n${failures.length} MISMATCH(ES):`)
  for (const f of failures) console.error('  ' + f)
  process.exit(1)
}
console.log('\nall values match the reference implementation exactly')
